#pragma once
int runGrid442(){juce::ScopedJuceInitialiser_GUI gui;LibraryPreparation::checksPaused=true;std::cout.setf(std::ios::unitbuf);try{
 auto require=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};auto root=LibraryStore::root().getChildFile("Per track grid");root.createDirectory();auto make=[&](juce::String name,double rate){auto audio=std::make_shared<AudioData>();audio->rate=rate;audio->path=root.getChildFile(name+".wav").getFullPathName();audio->buffer.setSize(1,(int)(rate*8));for(int i=0;i<audio->buffer.getNumSamples();++i)audio->buffer.setSample(0,i,.25f*std::sin(i*.025));LibraryStore::setPlaybackType({juce::File(audio->path)},2);return audio;};
 auto first=make("First",44100),second=make("Second",48000),third=make("Third",32000);Processor p(false);p.autoSave=false;p.trackOffline=true;p.trackStemsEnabled=false;p.trackVinyl=true;p.audio=first;p.split(4,false);p.trackMode=p.trackGridReady=p.trackGridEdited=true;p.trackGrid.bpm=120;p.trackGrid.anchors={{0,0},{first->rate*7,14}};p.nudgeTrackGrid(23);require(p.saveLoop(),"save first grid");require(p.installAudio(second,true,0,false)&&p.trackGrid.sampleOffset==0,"unsaved track does not inherit prior offset");p.trackMode=p.trackGridReady=p.trackGridEdited=true;p.trackGrid.bpm=120;p.trackGrid.anchors={{0,0},{second->rate*7,14}};p.nudgeTrackGrid(-7);require(p.saveLoop(),"save second grid");require(p.installAudio(third,true,0,false)&&p.trackGrid.sampleOffset==0,"second offset not carried to fresh track");require(p.installAudio(first,true,0,false)&&std::abs(p.trackGrid.sampleOffset/first->rate*1000-23)<1e-7,"first track saved offset restored");require(p.installAudio(second,true,0,false)&&std::abs(p.trackGrid.sampleOffset/second->rate*1000+7)<1e-7,"second track saved offset restored");
 TrackPanel panel(p);panel.setSize(1000,700);panel.sync();require(panel.nudgeForCheck(),"grid minus/plus still work");auto image=panel.createComponentSnapshot(panel.getLocalBounds());{juce::FileOutputStream file(LibraryStore::root().getChildFile("track-grid-ui.png"));juce::PNGImageFormat().writeImageToStream(image,file);}std::function<void(juce::Component&)> inspect=[&](juce::Component& c){if(auto* field=dynamic_cast<juce::TextEditor*>(&c))require(!field->getText().endsWith(" ms"),"millisecond offset field removed");for(auto* child:c.getChildren())inspect(*child);};inspect(panel);
 // Preparation records remain unchanged when the same cache is reused.
 auto file=root.getChildFile("Actual.wav");require(writeRenderedAudio(file,second->buffer,second->rate),"metadata fixture");auto hash=LibraryStore::fingerprint(file);TrackAnalyser::markPrepared(file,hash);auto revision=LibraryStore::kindRevision("track-prepared-v1.json").load();TrackAnalyser::markPrepared(file,hash);require(revision==LibraryStore::kindRevision("track-prepared-v1.json").load(),"unchanged prepared icon is not rewritten");auto entry=LibraryStore::database()->metadataEntry("track-prepared-v1.json",file.getFullPathName());require(entry["hash"].toString()==hash,"indexed prepared record lookup");
 std::cout<<"Track-specific grid offsets save/recall at 44.1/48/32 kHz; no offset carry; Grid +/- retained, ms field removed, native layout and unchanged prepared-record reuse passed\n";return 0;
 }catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 4421;}}
